const input = $input.first().json;
let alert;
if (input['Alert JSON'] !== undefined) {
  try { alert = typeof input['Alert JSON'] === 'string' ? JSON.parse(input['Alert JSON']) : input['Alert JSON']; }
  catch (e) { throw new Error('Invalid JSON in Alert JSON form field: ' + e.message); }
} else {
  const body = input.body ?? input;
  alert = typeof body === 'string' ? JSON.parse(body) : body;
}
const src_ip = alert.data?.srcip ?? alert.src_ip;
if (!src_ip || !/^(?:(?:\d{1,3}\.){3}\d{1,3}|[0-9a-fA-F:]+)$/.test(src_ip)) throw new Error('Missing or malformed source IP');
const octets = src_ip.split('.');
if (octets.length === 4 && octets.some(x => Number(x) > 255)) throw new Error('Invalid IPv4 octet');
const count = Number(alert.rule?.firedtimes ?? alert.failure_count ?? 0);
if (!Number.isFinite(count) || count < 0) throw new Error('Invalid failure count');
return [{json:{alert_id:'INC-HX-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),src_ip,username:String(alert.data?.dstuser ?? alert.username ?? 'unknown'),failure_count:count,target_host:String(alert.agent?.name ?? alert.target_host ?? 'unknown'),service:String(alert.data?.program_name ?? alert.service ?? 'sshd'),timestamp:String(alert.timestamp ?? new Date().toISOString()),wazuh_rule_id:String(alert.rule?.id ?? ''),wazuh_rule_level:Number(alert.rule?.level ?? 0),mitre_ids:alert.rule?.mitre?.id ?? []}}];

const alert = $('Extract Alert Fields').item.json;
const response = $input.first().json;
const d = response.data ?? response;
if (d.abuseConfidenceScore === undefined) throw new Error('AbuseIPDB response missing abuseConfidenceScore');
return [{json:{...alert,abuse_score:Number(d.abuseConfidenceScore ?? 0),isp:d.isp ?? null,domain:d.domain ?? null,total_reports:Number(d.totalReports ?? 0),last_reported:d.lastReportedAt ?? null,is_tor:d.isTor === true,country_code:d.countryCode ?? null,hostnames:d.hostnames ?? [],is_whitelisted:d.isWhitelisted === true}}];

const d = $input.first().json;
let risk_score = 0; const reasons = [];
if (d.abuse_score >= 80) {risk_score += 40; reasons.push('AbuseIPDB score >= 80 (+40)');}
if (d.is_tor === true) {risk_score += 25; reasons.push('Tor exit node (+25)');}
if (d.failure_count >= 50) {risk_score += 20; reasons.push('At least 50 failed attempts (+20)');}
if (d.username.toLowerCase() === 'root') {risk_score += 10; reasons.push('Root account targeted (+10)');}
if (d.total_reports >= 100) {risk_score += 5; reasons.push('At least 100 community reports (+5)');}
const severity = risk_score >= 90 ? 'CRITICAL' : risk_score >= 70 ? 'HIGH' : risk_score >= 40 ? 'MEDIUM' : 'LOW';
return [{json:{...d,risk_score,severity,reasons}}];

const d = $input.first().json;
const summary = ['SSH BRUTE-FORCE SECURITY ALERT',`Incident ID: ${d.alert_id}`,`Severity: ${d.severity}`,`Risk Score: ${d.risk_score}/100`,`Source IP: ${d.src_ip}`,`Target Host: ${d.target_host}`,`Username: ${d.username}`,`Service: ${d.service}`,`Failed Attempts: ${d.failure_count}`,`Event Time: ${d.timestamp}`,`AbuseIPDB Score: ${d.abuse_score}/100`,`Abuse Reports: ${d.total_reports}`,`Tor Exit Node: ${d.is_tor ? 'Yes':'No'}`,`Whitelisted: ${d.is_whitelisted ? 'Yes':'No'}`,`ISP: ${d.isp ?? 'Unknown'}`,`Country: ${d.country_code ?? 'Unknown'}`,`Last Reported: ${d.last_reported ?? 'Unknown'}`,'Risk Factors:',...(d.reasons.length ? d.reasons.map(r=>'- '+r) : ['- No scoring thresholds met']),'Analyst action: Review authentication and network logs; validate context before escalation.'].join('\n');
return [{json:{...d,incident_summary:summary}}];

const card = $input.first().json;
const d = $('Build Incident Summary').item.json;
const esc = v => String(v ?? 'Unknown').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
const url = typeof card.shortUrl === 'string' && /^https:\/\/trello\.com\//.test(card.shortUrl) ? card.shortUrl : (typeof card.url === 'string' && /^https:\/\/trello\.com\//.test(card.url) ? card.url : '');
const fields = [['Incident ID',d.alert_id],['Source IP',d.src_ip],['Target Host',d.target_host],['Username',d.username],['Service',d.service],['Failures',d.failure_count],['Risk Score',d.risk_score+'/100'],['AbuseIPDB',d.abuse_score+'/100'],['ISP',d.isp],['Country',d.country_code],['Reports',d.total_reports],['Tor Exit',d.is_tor?'Yes':'No'],['Whitelisted',d.is_whitelisted?'Yes':'No'],['Last Reported',d.last_reported]];
const body = fields.map(([k,v])=>`<div class="item"><small>${esc(k)}</small><strong>${esc(v)}</strong></div>`).join('');
const ticket = url ? `<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">View Investigation Ticket</a>` : '<p>Ticket URL not returned.</p>';
const page = `<!doctype html><html><head><meta charset="utf-8"><title>Brute-Force Incident</title><style>body{font-family:system-ui;background:#101827;color:#e9eef7;padding:28px;max-width:900px;margin:auto}h1{font-size:26px}.badge{background:#b91c1c;padding:8px 14px;border-radius:12px;font-weight:700}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px;margin-top:25px}.item{background:#1e293b;border-radius:12px;padding:15px}.item small{display:block;color:#aab8cd;margin-bottom:8px}.item strong{overflow-wrap:anywhere}a{color:#93c5fd}pre{white-space:pre-wrap;background:#1e293b;padding:16px;border-radius:12px}</style></head><body><h1>SSH Brute-Force Incident</h1><span class="badge">${esc(d.severity)}</span><div class="grid">${body}</div><h2>Investigation</h2>${ticket}<h2>Incident Summary</h2><pre>${esc(d.incident_summary)}</pre></body></html>`;
return [{json:{html:page,alert_id:d.alert_id,severity:d.severity,trello_url:url}}];
